mapper.update:
UPDATE police_phone
SET heartbeat_sequence = #{sequence},
    last_heartbeat_event_id = #{eventId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler},
    last_heartbeat_at = #{receivedAt},
    last_sync_at = COALESCE(#{lastSyncAt}, last_sync_at),
    version = version + 1,
    updated_at = #{receivedAt}
WHERE id = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND heartbeat_sequence < #{sequence}

mapper.select:
SELECT version
FROM fcm_token
WHERE police_phone_id = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND app_instance_id = #{appInstanceId}
  AND status = 'ACTIVE'
LIMIT 1

mapper.update:
UPDATE fcm_token
SET status = 'REVOKED',
    revoked_at = #{revokedAt}
WHERE police_phone_id = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND app_instance_id = #{appInstanceId}
  AND status = 'ACTIVE'

UPDATE fcm_token
SET status = 'REVOKED',
    revoked_at = #{revokedAt}
WHERE police_phone_id = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND account_id = #{accountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND status = 'ACTIVE'

mapper.select:
SELECT id, police_phone_id, app_instance_id, token_ciphertext, token_hash, status, version FROM fcm_token WHERE status = 'ACTIVE' AND account_id IN
#{accountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
ORDER BY police_phone_id ASC, app_instance_id ASC, id ASC
